  addDeco(v3(-1.5f, -0.4f, RIVER_Z0 + 16), v3(3.0f, 0.3f, 3.5f), 0.4f, RGB(130, 130, 126)); addDeco(v3(2.5f, -0.6f, RIVER_Z0 + 20), v3(2.5f, 0.3f, 3.0f), -0.6f, RGB(140, 140, 136));
  for (int s = -1; s <= 1; s += 2) addBox(s * 3 - 0.6f, RIVER_Z0 + 11, s * 3 + 0.6f, RIVER_Z0 + 13, -1, 0.3f, RGB(110, 110, 106), false);
  addSign(0, 2.2f, RIVER_Z0 - 4, "МОСТ РАЗРУШЕН. ОБХОД ПО Ж/Д МОСТУ ->", RGB(255, 220, 120));
  // железнодорожный мост и путь
  float x = RAIL_X;
