  for (int k = 0; k < 2; k++) { float z = 1990 + k * 14; addBox(x - 1.5f, z, x + 1.5f, z + 12, 0.4f, 3.6f, k ? RGB(90, 60, 40) : RGB(60, 80, 100), true); }   // вагоны
