  for (float z = 2960; z < 3940; z += 4) for (int s = -1; s <= 1; s += 2) addBox(s < 0 ? -ROAD_HW - 4 : ROAD_HW, z, s < 0 ? -ROAD_HW : ROAD_HW + 4, z + 4, 0, 0.1f, RGB(150, 150, 150), false, BK_FLOOR);   // тротуары
