    for (int k = 0; k < 16; k++) { float bx = s * (ROAD_HW + 8 + wr(0, 40)), bz = wr(4490, 4950); if (occupied(bx - 2, bz - 2, bx + 2, bz + 2, 1)) continue;
      addBox(bx - 1.6f, bz - 0.4f, bx + 1.6f, bz + 0.4f, 0, 1.0f, RGB(150, 140, 100), true); }   // мешки с песком
