static void genWorld() {
  boxes.clear(); roofs.clear(); houses.clear(); loots.clear(); trees.clear(); lamps.clear(); signs.clear(); pumps.clear(); cars.clear();
  panels.clear(); waters.clear(); decos.clear(); fields.clear(); occ.clear();
  BK.assign((size_t)((ROAD_LEN + 200 - ZMIN) / CELL) + 2, Bucket());
  wrng = 1337u;
  // особые места - первыми
  addHouse(-(ROAD_HW + 7 + 6), 260, 12, 14, -1, HT_SHOP, 900);
  addHouse(ROAD_HW + 7 + 6, 1600, 12, 14, 1, HT_SHOP, 901);
  addGasStation(1760);
  addHouse(-(ROAD_HW + 7 + 6), 5250, 12, 14, -1, HT_SHOP, 902);
  addFarm(); addRiver(); addSwamp(); addCemetery(); addCity(); addMilitary();
  for (int i = 0; i < NBARRIER; i++) addBarrier(BARRIERS[i], i == 0 ? 1 : (i == 2 ? 2 : 0));
  // обычные участки по зонам
  for (float z = 12; z < ROAD_LEN - 30; z += 30) {
    int zt = ZONES[zoneAt(z)].type;
    for (int side = -1; side <= 1; side += 2) {
      unsigned sd = (unsigned)(z * 13 + side * 7 + 99);
      if (zt == ZT_VILLAGE) {
        for (int row = 0; row < 1 + (hf(sd + 1) < 0.35f ? 1 : 0); row++) {
          float pr = 0.75f; if (row) pr *= 0.6f; if (hf(sd + 17 * row) > pr) continue;
          float w = wr(7.5f, 10), d = wr(8.5f, 11.5f), cx = side * (ROAD_HW + 6.5f + w * 0.5f + row * 17 + wr(0, 2.5f)), cz = z + wr(-3, 3);
          if (occupied(cx - w * 0.5f, cz - d * 0.5f, cx + w * 0.5f, cz + d * 0.5f, 2.5f)) continue;
          addHouse(cx, cz, w, d, side, HT_HOUSE, sd + row * 31);
          float fx = side < 0 ? houses.back().x1 + 2.6f : houses.back().x0 - 2.6f;
          if (row == 0 && hf(sd + 5) < 0.6f) { addBox(fx - 0.05f, cz - d * 0.5f - 1, fx + 0.05f, cz - 1.3f, 0, 1.1f, RGB(130, 100, 70), true); addBox(fx - 0.05f, cz + 1.3f, fx + 0.05f, cz + d * 0.5f + 1, 0, 1.1f, RGB(130, 100, 70), true); }
        }
        for (int k = 0; k < 3; k++) { float tx = side * (ROAD_HW + 4 + wr(0, 50)), tz = z + wr(0, 30); if (!occupied(tx - 1, tz - 1, tx + 1, tz + 1, 1.5f) && fabsf(tx) > ROAD_HW + 3) addTree(tx, tz, wri(2)); }
        if (fmodf(z, 60) < 30) addLamp(side * (ROAD_HW + 1.4f), z + 15, hf(sd + 77) < 0.8f);
      } else if (zt == ZT_FOREST || zt == ZT_DARKFOREST) {
        int n = zt == ZT_DARKFOREST ? 22 : 14;
        for (int k = 0; k < n; k++) { float tx = side * (ROAD_HW + 3.5f + wr(0, 60)), tz = z + wr(0, 30); if (!occupied(tx - 1, tz - 1, tx + 1, tz + 1, 1.5f)) addTree(tx, tz, zt == ZT_DARKFOREST ? (wri(5) ? 0 : 2) : (wri(3) ? 0 : 1)); }
        if (hf(sd + 9) < 0.25f) { float lx = side * (ROAD_HW + 6 + wr(0, 20)), lz = z + wr(0, 30); if (!occupied(lx - 3, lz - 1, lx + 3, lz + 1, 1)) addBox(lx - 2.5f, lz - 0.3f, lx + 2.5f, lz + 0.3f, 0, 0.6f, RGB(96, 70, 46), true); }
        if (hf(sd + 2) < 0.1f) { float w = 5.5f, d = 6.5f, cx = side * (ROAD_HW + 9 + w * 0.5f), cz = z + 10; if (!occupied(cx - 4, cz - 4, cx + 4, cz + 4, 3)) addHouse(cx, cz, w, d, side, HT_HUT, sd + 50); }
      } else if (zt == ZT_FIELD || zt == ZT_FARM) {
        for (int k = 0; k < 3; k++) { float tx = side * (ROAD_HW + 6 + wr(0, 58)), tz = z + wr(0, 30); if (!occupied(tx - 1, tz - 1, tx + 1, tz + 1, 1.5f)) addTree(tx, tz, 1); }
        if (zt == ZT_FIELD && hf(sd + 3) < 0.35f) { float hx = side * (ROAD_HW + 10 + wr(0, 30)), hz = z + wr(0, 25); if (!occupied(hx - 2, hz - 2, hx + 2, hz + 2, 1)) addBox(hx - 1.2f, hz - 1.2f, hx + 1.2f, hz + 1.2f, 0, 1.6f, RGB(200, 170, 80), true); }
        if (zt == ZT_FIELD && hf(sd + 4) < 0.16f) { float w = 7.5f, d = 9, cx = side * (ROAD_HW + 8 + w * 0.5f), cz = z + 12; if (!occupied(cx - 5, cz - 5, cx + 5, cz + 5, 3)) addHouse(cx, cz, w, d, side, HT_HOUSE, sd + 60); }
      } else if (zt == ZT_RIVER || zt == ZT_CEMETERY) {
        for (int k = 0; k < 4; k++) { float tx = side * (ROAD_HW + 5 + wr(0, 55)), tz = z + wr(0, 30); if (!occupied(tx - 1, tz - 1, tx + 1, tz + 1, 1.5f)) addTree(tx, tz, wri(2)); }
      } else if (zt == ZT_BORDER) {
        if (hf(sd + 6) < 0.4f) { float tx = side * (ROAD_HW + 8 + wr(0, 20)), tz = z + wr(0, 20); if (!occupied(tx - 3, tz - 3, tx + 3, tz + 3, 1)) { addRoof(tx - 2, tz - 3, tx + 2, tz + 3, 0, 2.2f, RGB(80, 96, 60)); addBox(tx - 1.9f, tz - 2.9f, tx + 1.9f, tz + 2.9f, 0, 1.2f, RGB(80, 96, 60), true); reserve(tx - 2, tz - 3, tx + 2, tz + 3); } }
        for (int k = 0; k < 2; k++) { float tx = side * (ROAD_HW + 20 + wr(0, 40)), tz = z + wr(0, 30); addTree(tx, tz, 1); }
        if (hf(sd + 8) < 0.12f) { float w = 8, d = 9, cx = side * (ROAD_HW + 8 + w * 0.5f), cz = z + 15; if (!occupied(cx - 5, cz - 5, cx + 5, cz + 5, 3)) addHouse(cx, cz, w, d, side, HT_HOUSE, sd + 70); }
      }
    }
    // брошенные машины: мало бензина, часто сел аккумулятор
    unsigned cs = (unsigned)(z * 31 + 5); int zt2 = ZONES[zoneAt(z)].type;
    if (zt2 != ZT_CITY && hf(cs) < (zt2 == ZT_BORDER ? 0.6f : 0.36f)) {
      int s2 = hf(cs + 1) < 0.5f ? -1 : 1; bool onRoad = hf(cs + 2) < 0.4f; float x = onRoad ? s2 * wr(1.2f, 2.6f) : s2 * (ROAD_HW + 1.4f), cz = z + wr(0, 20);
      if (!occupied(x - 1, cz - 2.5f, x + 1, cz + 2.5f, 0.5f)) addCar(x, cz, (hf(cs + 4) < 0.5f ? 0.0f : 3.14159f) + wr(-0.35f, 0.35f), hf(cs + 3) < 0.4f, wreckFuel(cs + 5), cs);
    }
  }
  addCar(3.0f, 26, 0.05f, false, 4, 4242); cars.back().model = 0; cars.back().col = RGB(150, 154, 160); cars.back().hp = 90; cars.back().dead = false;   // у старта: 4 литра
  // КПП
  { float z = ROAD_LEN;
    for (int k = -1; k <= 1; k += 2) { float bx = k * (ROAD_HW + 3.5f);
      addBox(bx - 2, z - 4, bx + 2, z + 4, 0, 3.0f, RGB(210, 212, 205), true, BK_WALL); addBox(bx - 2.3f, z - 4.3f, bx + 2.3f, z + 4.3f, 3.0f, 3.3f, RGB(60, 90, 60), false);
      addBox(bx - 0.6f, z - 4.06f, bx + 0.6f, z - 3.94f, 1.0f, 2.2f, RGB(40, 58, 78), false, BK_GLASS);
      addBox(k * (ROAD_HW + 0.2f) - 0.2f, z - 0.2f, k * (ROAD_HW + 0.2f) + 0.2f, z + 0.2f, 0, 1.2f, RGB(220, 220, 220), true);
      addBox(k * 40 - 30, z + 3, k * 40 + 30, z + 3.2f, 0, 3.2f, RGB(120, 120, 116), true);
      addBox(k * (ROAD_HW + 9) - 0.15f, z - 2, k * (ROAD_HW + 9) + 0.15f, z - 1.7f, 0, 7, RGB(200, 200, 200), false);
      addBox(k * (ROAD_HW + 9) + 0.15f, z - 1.9f, k * (ROAD_HW + 9) + 1.6f, z - 1.8f, 5.6f, 6.2f, k < 0 ? RGB(240, 240, 240) : RGB(30, 80, 190), false, BK_LIT); }
    for (int i = 0; i < 8; i++) addBox(-ROAD_HW + i * 1.05f, z - 0.08f, -ROAD_HW + i * 1.05f + 1.05f, z + 0.08f, 1.0f, 1.16f, i & 1 ? RGB(240, 240, 240) : RGB(210, 30, 30), false, BK_LIT);
    addBox(-ROAD_HW - 1, z - 20.2f, ROAD_HW + 1, z - 19.8f, 5.2f, 6.4f, RGB(20, 110, 70), false, BK_LIT);
    for (int k = -1; k <= 1; k += 2) addBox(k * (ROAD_HW + 1) - 0.15f, z - 20.15f, k * (ROAD_HW + 1) + 0.15f, z - 19.85f, 0, 5.2f, RGB(150, 150, 150), true);
    addSign(0, 5.8f, z - 20.3f, "ГРАНИЦА. КПП", RGB(255, 255, 255));
    addBox(-60, z + 3.2f, 60, z + 40, 0, 0.01f, RGB(96, 108, 90), false); }
  for (float z = 5880; z < ROAD_LEN; z += 30) for (int k = -1; k <= 1; k += 2) addLamp(k * (ROAD_HW + 1.4f), z + (k > 0 ? 15 : 0), true);
  // край мира
  for (int k = -1; k <= 1; k += 2) addBox(k * WORLD_X - 0.5f, ZMIN, k * WORLD_X + 0.5f, ROAD_LEN + 20, 0, 3, RGB(40, 56, 40), true);
  for (float z = ZMIN; z < ROAD_LEN + 10; z += 9) { if (z > RIVER_Z0 - 3 && z < RIVER_Z1 + 3) continue; for (int k = -1; k <= 1; k += 2) addTree(k * (WORLD_X - 2 - wr(0, 4)), z + wr(0, 8), 0); }
  addBox(-WORLD_X, -32, WORLD_X, -30, 0, 2.5f, RGB(90, 70, 50), true);
}

// ---------- столкновения ----------
static bool inHouse(float x, float z, int &hi) {
  hi = -1; int b = bkOf(z); if (b < 0) return false;
  const std::vector<int> &L = BK[b].house;
  for (size_t i = 0; i < L.size(); i++) { const House &h = houses[L[i]]; if (x > h.x0 && x < h.x1 && z > h.z0 && z < h.z1) { hi = L[i]; return true; } }
  return false;
}
static bool inSwamp(float x, float z) {
  if (z < 2150 || z > 2660) return false;
  for (size_t i = 0; i < waters.size(); i++) { const Water &w = waters[i]; if (w.kind == 1 && x > w.x0 && x < w.x1 && z > w.z0 && z < w.z1) return true; }
  return false;
}
static bool collide(float &x, float &z, float r, float y0, float y1) {
  bool hit = false;
  for (int it = 0; it < 3; it++) {
    bool any = false;
    for (int b = bkOf(z - r - 1); b <= bkOf(z + r + 1); b++) {
      const std::vector<int> &L = BK[b].box;
      for (size_t i = 0; i < L.size(); i++) {
        const WBox &q = boxes[L[i]]; if (!q.solid || q.y1 < y0 || q.y0 > y1) continue;
        if (x < q.x0 - r || x > q.x1 + r || z < q.z0 - r || z > q.z1 + r) continue;
        float cx = clampf(x, q.x0, q.x1), cz = clampf(z, q.z0, q.z1), dx = x - cx, dz = z - cz, d2 = dx * dx + dz * dz;
        if (d2 >= r * r) continue;
        if (d2 > 1e-8f) { float d = sqrtf(d2), k = (r - d) / d; x += dx * k; z += dz * k; }
        else { float px0 = x - q.x0, px1 = q.x1 - x, pz0 = z - q.z0, pz1 = q.z1 - z, m = fminv(fminv(px0, px1), fminv(pz0, pz1));
          if (m == px0) x = q.x0 - r; else if (m == px1) x = q.x1 + r; else if (m == pz0) z = q.z0 - r; else z = q.z1 + r; }
        any = hit = true;
      }
    }
    if (!any) break;
  }
  for (int b = bkOf(z - 2); b <= bkOf(z + 2); b++) { const std::vector<int> &L = BK[b].tree;
    for (size_t i = 0; i < L.size(); i++) { const Tree &t = trees[L[i]]; if (t.kind < 0) continue; float dx = x - t.x, dz = z - t.z, rr = r + 0.28f, d2 = dx * dx + dz * dz;
      if (d2 < rr * rr && d2 > 1e-6f) { float d = sqrtf(d2); x = t.x + dx / d * rr; z = t.z + dz / d * rr; hit = true; } } }
  return hit;
}
static float rayBoxes(V3 o, V3 d, float tmax, V3 *hitN) {
  float best = tmax; V3 bn = v3(0, 1, 0);
  float zA = fminv(o.z, o.z + d.z * tmax), zB = fmaxv(o.z, o.z + d.z * tmax);
  for (int b = bkOf(zA - 1); b <= bkOf(zB + 1); b++) {
    const std::vector<int> &L = BK[b].box;
    for (size_t i = 0; i < L.size(); i++) {
      const WBox &q = boxes[L[i]]; if (!q.solid && q.kind != BK_GLASS) continue;
      if (q.kind == BK_HIDDEN && q.col == 0 && (q.y1 == 2.5f || q.y1 == 1.51f)) continue;   // вода и ограда не останавливают пули
      float t0 = 0, t1 = best; V3 n = v3(0, 0, 0); bool ok = true;
      const float lo[3] = {q.x0, q.y0, q.z0}, hi[3] = {q.x1, q.y1, q.z1}, oo[3] = {o.x, o.y, o.z}, dd[3] = {d.x, d.y, d.z};
      for (int a = 0; a < 3 && ok; a++) {
        if (fabsf(dd[a]) < 1e-7f) { if (oo[a] < lo[a] || oo[a] > hi[a]) ok = false; continue; }
        float ta = (lo[a] - oo[a]) / dd[a], tb = (hi[a] - oo[a]) / dd[a]; float sgn = -1;
        if (ta > tb) { float t = ta; ta = tb; tb = t; sgn = 1; }
        if (ta > t0) { t0 = ta; n = v3(a == 0 ? sgn : 0, a == 1 ? sgn : 0, a == 2 ? sgn : 0); }
        if (tb < t1) t1 = tb; if (t0 > t1) ok = false;
      }
      if (ok && t0 < best && t0 > 0.0f) { best = t0; bn = n; }
    }
  }
  if (hitN) *hitN = bn;
  return best;
}

// =====================================================================
//  ДОРОГА К ГРАНИЦЕ: сеть для игры с другом (UDP, одна Wi-Fi сеть)
//  Хост ведёт мир (зомби, машины, тайники), каждый игрок ведёт себя сам.
// =====================================================================
#ifdef _WIN32
  #include <winsock2.h>
  #include <ws2tcpip.h>
  #ifdef _MSC_VER
    #pragma comment(lib, "ws2_32.lib")
  #endif
  typedef SOCKET sock_t;
  #define BADSOCK INVALID_SOCKET
  static void sockClose(sock_t s) { closesocket(s); }
  static void sockNB(sock_t s) { u_long m = 1; ioctlsocket(s, FIONBIO, &m); }
#else
  #include <sys/types.h>
  #include <sys/socket.h>
  #include <netinet/in.h>
  #include <arpa/inet.h>
  #include <fcntl.h>
  #include <errno.h>
  typedef int sock_t;
  #define BADSOCK (-1)
  static void sockClose(sock_t s) { close(s); }
  static void sockNB(sock_t s) { int f = fcntl(s, F_GETFL, 0); fcntl(s, F_SETFL, f | O_NONBLOCK); }
#endif

static const unsigned short NET_PORT = 27315;
static const unsigned NET_MAGIC = 0x5A42524Eu;   // ZBRN
static const int NET_VER = 1;
enum { NET_OFF, NET_HOST, NET_CLIENT };
static int netMode = NET_OFF;
static bool netPeer = false;                     // есть ли связь с другом
static bool netStarted = false;                  // игра началась (после лобби)
static sock_t netSock = BADSOCK;
static sockaddr_in netPeerAddr, netFoundAddr;
static bool netFound = false, netBye = false;   // netBye - друг сам вышел из игры
static float netLastRecv = 0, netSendT = 0, netWorldT = 0, netWorld2T = 0, netDiscT = 0;
static char manualIP[24] = "";
static char netMyIP[32] = "", netFoundIP[32] = "", netStatus[96] = "";

// пакеты
enum { PK_DISCOVER = 1, PK_HERE, PK_JOIN, PK_WELCOME, PK_PING, PK_PSTATE, PK_WORLD, PK_WORLD2, PK_BYE };
// события с подтверждением (доставляются по порядку)
enum { EV_HIT = 1, EV_KILL, EV_NOISE, EV_PICK, EV_GIVE, EV_DMG, EV_REVIVE, EV_WIN, EV_LOSE, EV_CARSET, EV_SEARCH, EV_START, EV_SAY };
struct NetEv { unsigned seq; unsigned char type, pad[3]; int i0, i1; float f[4]; };
static std::vector<NetEv> netOut;                // ещё не подтверждённые
static unsigned netOutSeq = 0, netInSeq = 0;     // последний отправленный / последний принятый по порядку
static std::vector<NetEv> netInbox;              // принятые, ждут обработки игрой

static void netEvent(int type, int i0 = 0, int i1 = 0, float f0 = 0, float f1 = 0, float f2 = 0, float f3 = 0) {
  if (netMode == NET_OFF || !netPeer) return;
  NetEv e; memset(&e, 0, sizeof e); e.seq = ++netOutSeq; e.type = (unsigned char)type; e.i0 = i0; e.i1 = i1; e.f[0] = f0; e.f[1] = f1; e.f[2] = f2; e.f[3] = f3;
  netOut.push_back(e); if (netOut.size() > 400) netOut.erase(netOut.begin());
}

// запись и чтение пакета
struct PBuf { unsigned char d[1400]; int n, r; bool bad; };
static void pbInit(PBuf &b) { b.n = 0; b.r = 0; b.bad = false; }
static void wU8(PBuf &b, int v) { if (b.n < (int)sizeof b.d) b.d[b.n++] = (unsigned char)v; else b.bad = true; }
static void wU16(PBuf &b, int v) { wU8(b, v & 255); wU8(b, (v >> 8) & 255); }
static void wU32(PBuf &b, unsigned v) { wU16(b, (int)(v & 0xFFFF)); wU16(b, (int)(v >> 16)); }
static void wF(PBuf &b, float f) { unsigned u; memcpy(&u, &f, 4); wU32(b, u); }
static int rU8(PBuf &b) { if (b.r < b.n) return b.d[b.r++]; b.bad = true; return 0; }
static int rU16(PBuf &b) { int a = rU8(b); return a | (rU8(b) << 8); }
static int rI16(PBuf &b) { int v = rU16(b); return v >= 32768 ? v - 65536 : v; }
static unsigned rU32(PBuf &b) { unsigned a = (unsigned)rU16(b); return a | ((unsigned)rU16(b) << 16); }
static float rF(PBuf &b) { unsigned u = rU32(b); float f; memcpy(&f, &u, 4); return f; }
static void wHead(PBuf &b, int type) {
  pbInit(b); wU32(b, NET_MAGIC); wU8(b, NET_VER); wU8(b, type); wU32(b, netInSeq);
  int n = 0; for (size_t i = 0; i < netOut.size() && n < 12; i++) n++;
  wU8(b, n);
  for (int i = 0; i < n; i++) { const NetEv &e = netOut[i]; wU32(b, e.seq); wU8(b, e.type); wU32(b, (unsigned)e.i0); wU32(b, (unsigned)e.i1); for (int k = 0; k < 4; k++) wF(b, e.f[k]); }
}

static bool netOpen(bool host) {
#ifdef _WIN32
  static bool wsa = false; if (!wsa) { WSADATA w; if (WSAStartup(MAKEWORD(2, 2), &w) != 0) return false; wsa = true; }
#endif
  if (netSock != BADSOCK) { sockClose(netSock); netSock = BADSOCK; }
  netSock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP); if (netSock == BADSOCK) return false;
  int yes = 1; setsockopt(netSock, SOL_SOCKET, SO_BROADCAST, (const char *)&yes, sizeof yes); setsockopt(netSock, SOL_SOCKET, SO_REUSEADDR, (const char *)&yes, sizeof yes);
  sockaddr_in a; memset(&a, 0, sizeof a); a.sin_family = AF_INET; a.sin_addr.s_addr = htonl(INADDR_ANY); a.sin_port = htons(host ? NET_PORT : 0);
  if (bind(netSock, (sockaddr *)&a, sizeof a) != 0) { sockClose(netSock); netSock = BADSOCK; return false; }
  sockNB(netSock);
  return true;
}
// свой адрес в сети: через "подключение" UDP-сокета (пакеты не уходят)
static unsigned netLocalIP(const char *probe) {
  sock_t s = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP); if (s == BADSOCK) return 0;
  sockaddr_in a; memset(&a, 0, sizeof a); a.sin_family = AF_INET; a.sin_port = htons(9); a.sin_addr.s_addr = inet_addr(probe);
  unsigned ip = 0;
  if (connect(s, (sockaddr *)&a, sizeof a) == 0) { sockaddr_in m; socklen_t l = sizeof m; if (getsockname(s, (sockaddr *)&m, &l) == 0) ip = ntohl(m.sin_addr.s_addr); }
  sockClose(s); return ip;
}
static void ipStr(unsigned ip, char *o, int n) { snprintf(o, n, "%u.%u.%u.%u", (ip >> 24) & 255, (ip >> 16) & 255, (ip >> 8) & 255, ip & 255); }
static void netFindMyIP() {
  const char *pr[3] = {"192.168.43.255", "10.255.255.255", "8.8.8.8"}; unsigned ip = 0;
  for (int i = 0; i < 3 && (!ip || (ip >> 24) == 127); i++) ip = netLocalIP(pr[i]);
  if (ip && (ip >> 24) != 127) ipStr(ip, netMyIP, sizeof netMyIP); else snprintf(netMyIP, sizeof netMyIP, "НЕИЗВЕСТЕН");
}
static void netSendTo(const PBuf &b, const sockaddr_in &to) { if (netSock != BADSOCK && !b.bad) sendto(netSock, (const char *)b.d, b.n, 0, (const sockaddr *)&to, sizeof to); }
static void netSend(const PBuf &b) { if (netPeer || (netStarted && !netBye)) netSendTo(b, netPeerAddr); }   // во время игры шлём и при обрыве: вдруг связь вернётся
static void netReset() {
  netOut.clear(); netInbox.clear(); netOutSeq = netInSeq = 0; netPeer = false; netStarted = false; netFound = false; netBye = false; netLastRecv = 0;
}
static void netClose() {
  if (netSock != BADSOCK) { if (netPeer) { PBuf b; wHead(b, PK_BYE); for (int i = 0; i < 3; i++) netSend(b); } sockClose(netSock); netSock = BADSOCK; }
  netMode = NET_OFF; netReset();
}
static bool netHost() { netReset(); if (!netOpen(true)) { snprintf(netStatus, sizeof netStatus, "НЕ УДАЛОСЬ ОТКРЫТЬ ПОРТ %d", NET_PORT); return false; } netMode = NET_HOST; netFindMyIP(); snprintf(netStatus, sizeof netStatus, "ЖДЁМ ДРУГА..."); return true; }
static bool netJoinMode() { netReset(); if (!netOpen(false)) { snprintf(netStatus, sizeof netStatus, "СЕТЬ НЕДОСТУПНА"); return false; } netMode = NET_CLIENT; netFindMyIP(); snprintf(netStatus, sizeof netStatus, "ИЩЕМ ИГРУ..."); return true; }
static void netDiscover(const char *manualIP) {
  PBuf b; pbInit(b); wU32(b, NET_MAGIC); wU8(b, NET_VER); wU8(b, PK_DISCOVER);
  sockaddr_in a; memset(&a, 0, sizeof a); a.sin_family = AF_INET; a.sin_port = htons(NET_PORT);
  if (manualIP && *manualIP) { a.sin_addr.s_addr = inet_addr(manualIP); netSendTo(b, a); return; }
  unsigned targets[6]; int nt = 0; targets[nt++] = 0xFFFFFFFFu; targets[nt++] = 0x7F000001u;
  unsigned me = 0; const char *pr[3] = {"192.168.43.255", "10.255.255.255", "8.8.8.8"};
  for (int i = 0; i < 3; i++) { me = netLocalIP(pr[i]); if (me && (me >> 24) != 127) { targets[nt++] = (me & 0xFFFFFF00u) | 255u; targets[nt++] = (me & 0xFFFFFF00u) | 1u; } if (nt >= 6) break; }
  for (int i = 0; i < nt; i++) { a.sin_addr.s_addr = htonl(targets[i]); netSendTo(b, a); }
}
static void netJoin() { if (!netFound) return; netPeerAddr = netFoundAddr; netPeer = true; netLastRecv = 0; PBuf b; wHead(b, PK_JOIN); netSend(b); snprintf(netStatus, sizeof netStatus, "ПОДКЛЮЧАЕМСЯ..."); }

// приём: события в netInbox, состояние - в обработчик игры
static void netHandlePacket(int type, PBuf &b);    // в g25_netsync.cpp
static void netPoll(float dt) {
  if (netSock == BADSOCK) return;
  netLastRecv += dt;
  for (int guard = 0; guard < 200; guard++) {
    PBuf b; pbInit(b); sockaddr_in from; socklen_t fl = sizeof from;
    int n = (int)recvfrom(netSock, (char *)b.d, sizeof b.d, 0, (sockaddr *)&from, &fl);
    if (n <= 0) break;
    b.n = n; if (rU32(b) != NET_MAGIC || rU8(b) != NET_VER) continue;
    int type = rU8(b);
    if (type == PK_DISCOVER) { if (netMode == NET_HOST && !netStarted) { PBuf r; pbInit(r); wU32(r, NET_MAGIC); wU8(r, NET_VER); wU8(r, PK_HERE); netSendTo(r, from); } continue; }
    if (type == PK_HERE) { if (netMode == NET_CLIENT && !netPeer) { netFound = true; netFoundAddr = from; ipStr(ntohl(from.sin_addr.s_addr), netFoundIP, sizeof netFoundIP); snprintf(netStatus, sizeof netStatus, "НАЙДЕНА ИГРА: %s", netFoundIP); } continue; }
    if (type == PK_JOIN && netMode == NET_HOST) {
      bool same = netPeer && netPeerAddr.sin_addr.s_addr == from.sin_addr.s_addr && netPeerAddr.sin_port == from.sin_port;
      if (!same && (netStarted || (netPeer && netLastRecv < 6))) continue;   // уже есть друг (в начатую игру чужих не пускаем)
      if (!same) { netReset(); netPeer = true; netPeerAddr = from; }
      snprintf(netStatus, sizeof netStatus, "ДРУГ ПОДКЛЮЧИЛСЯ");
    }
    if (!(netPeer || (netStarted && !netBye)) || from.sin_addr.s_addr != netPeerAddr.sin_addr.s_addr || from.sin_port != netPeerAddr.sin_port) continue;
    if (!netPeer && type != PK_BYE) { netPeer = true; snprintf(netStatus, sizeof netStatus, "СВЯЗЬ ВОССТАНОВЛЕНА"); }   // связь вернулась
    netLastRecv = 0;
    unsigned ack = rU32(b); int ne = rU8(b);
    while (!netOut.empty() && (int)(ack - netOut[0].seq) >= 0) netOut.erase(netOut.begin());   // подтверждённые
    for (int i = 0; i < ne && !b.bad; i++) { NetEv e; memset(&e, 0, sizeof e); e.seq = rU32(b); e.type = (unsigned char)rU8(b); e.i0 = (int)rU32(b); e.i1 = (int)rU32(b); for (int k = 0; k < 4; k++) e.f[k] = rF(b);
      if ((int)(e.seq - netInSeq) > 0) { netInSeq = e.seq; netInbox.push_back(e); } }   // по порядку; пропуск возможен, только если очередь переполнилась
    if (b.bad) continue;
    if (type == PK_BYE) { netPeer = false; netBye = true; snprintf(netStatus, sizeof netStatus, "ДРУГ ВЫШЕЛ ИЗ ИГРЫ"); if (!netStarted) netReset(); continue; }
    if (type == PK_WELCOME && netMode == NET_CLIENT) snprintf(netStatus, sizeof netStatus, "ПОДКЛЮЧЕНО. ЖДЁМ, КОГДА ДРУГ НАЧНЁТ");
    netHandlePacket(type, b);
  }
  if (netPeer && netLastRecv > 8) { netPeer = false; snprintf(netStatus, sizeof netStatus, "СВЯЗЬ С ДРУГОМ ПОТЕРЯНА"); }
}
// второй игрок (как его видим мы)
