static V3 eyePos() { if (pl.inCar >= 0) return v3(cars[pl.inCar].x, 1.6f, cars[pl.inCar].z) + rotOff(cars[pl.inCar].yaw, pl.seat ? 0.45f : -0.45f, 0, 0.1f); if (pl.downed) return v3(pl.x, 0.45f, pl.z); return v3(pl.x, 1.62f + sinf(pl.bob) * 0.035f, pl.z); }
static V3 lookDir() { return v3(sinf(pl.yaw) * cosf(pl.pitch), sinf(pl.pitch), cosf(pl.yaw) * cosf(pl.pitch)); }
