struct Part { V3 p, v; float life; u32 col; float sz; };
static std::vector<Part> parts;
static void burst(V3 p, int n, u32 col, float sp, float up, float sz) {
  for (int i = 0; i < n && parts.size() < 320; i++) { Part q; q.p = p; q.v = v3(frand(-sp, sp), frand(0, up), frand(-sp, sp)); q.life = frand(0.3f, 0.8f); q.col = col; q.sz = sz; parts.push_back(q); }
}
