static volatile float sReload = 0;
static volatile float sShot = 0, sShotType = 0, sMelee = 0, sThud = 0, sHurt = 0, sGroan = 0, sGroanF = 90, sEng = 0, sEngF = 40, sPick = 0, sStep = 0;
