  if (rpHere()) { char b2[64]; if (rp.downed) snprintf(b2, sizeof b2, "ДРУГ РАНЕН! ПОДНИМИ ЗА %d С", (int)ceilf(fmaxv(0.0f, rp.downT))); else snprintf(b2, sizeof b2, "ДРУГ: %d", (int)ceilf(fmaxv(0.0f, rp.hp)));
    drawTextSh(x, y + qh + fs * 12, b2, fs, rp.downed ? RGB(255, 90, 80) : RGB(120, 200, 255), 0); }
  else if (coopOn()) drawTextSh(x, y + qh + fs * 12, "НЕТ СВЯЗИ С ДРУГОМ", fs, RGB(255, 160, 80), 0);
  if (pl.bat > 0 || pl.can > 0) { char b2[64]; snprintf(b2, sizeof b2, "АККУМУЛЯТОР X%d  КАНИСТРА X%d", pl.bat, pl.can); drawTextSh(x, y + qh + fs * 3, b2, imax(1, fs - 1), RGB(220, 220, 190), 0); }
  if (gNK > 0.05f || pl.torch) { if (ub(x + (qw + fs * 2) * 2, y, qw, qh, pl.torch ? "ФОНАРЬ\nВКЛ" : "ФОНАРЬ\nВЫКЛ", true, pl.torch ? RGB(180, 160, 60) : RGB(70, 66, 70))) pl.torch = !pl.torch; }
  // дистанция и время
  float left = fmaxv(0.0f, ROAD_LEN - plZ());
  snprintf(b, sizeof b, "ДО КПП %.2f КМ", left / 1000.0f); drawTextSh(IW / 2, fs * 4, b, fs * 2, RGB(240, 240, 245), 1);
  int hh = (int)hours, mm = (int)((hours - hh) * 60); snprintf(b, sizeof b, "%02d:%02d %s", hh, mm, dayK > 0.5f ? "ДЕНЬ" : "НОЧЬ"); drawTextSh(IW / 2, fs * 21, b, fs, dayK > 0.5f ? RGB(255, 230, 150) : RGB(150, 170, 255), 1);
  // деньги и пауза
  char m[32]; fmtNum(m, sizeof m, pl.money); snprintf(b, sizeof b, "%s Р", m); drawTextSh(IW - fs * 28, fs * 6, b, fs * 2, RGB(150, 240, 150), 2);
  if (ub(IW - fs * 22, fs * 3, fs * 18, fs * 14, "II", true, RGB(60, 64, 80))) { gs = GS_PAUSE; fireHeld = false; }
  drawCompass(); if (!mapBig) drawMiniMap();
  { int bi = bossIdx(); if (bi >= 0) { const Zb &q = zs[bi]; float dx = q.x - plX(), dz = q.z - plZ(); if (dx * dx + dz * dz < 80 * 80) { float mh = ZD[ZB_BOSS].hp * (diff == 0 ? 0.7f : (diff == 2 ? 1.3f : 1.0f));
      int bw2 = IW * 45 / 100; bar(IW / 2 - bw2 / 2, IH * 18 / 100, bw2, fs * 8, q.hp / mh, RGB(160, 40, 200), "ГИГАНТ"); } } }
